static lstr L10788 = {0, 4150, "// std/arena: values in slots, reached through generation-checked handles (D118 item 2).\012//\012// A graph with cycles keeps its nodes in an Arena and refers to them with\012// Handle values. A handle is a slot index and the generation the slot had when\012// the value went in. Removing a value, or clearing the arena, raises the\012// generation, so an old handle finds nothing. A handle from another arena is\012// not detected: it reads whatever that slot of this arena holds.\012\012import * as Arrays from \"std/array\"\012\012export opaque struct Handle<T> derives Equatable, Hashable, Show {\012  index: int\012  generation: int\012}\012\012export opaque struct Arena<T> {\012  slots: Array<Option<T>>\012  generations: Array<int>\012  free: Array<int>\012  freeCount: int\012  count: int\012}\012\012export function create<T>(): Arena<T> uses alloc {\012  return Arena<T> { slots: [], generations: [], free: [], freeCount: 0, count: 0 }\012}\012\012export function insert<T>(mutable arena: Arena<T>, value: T): Handle<T> uses alloc {\012  // Reuse the last freed slot, or add a new one.\012  if (arena.freeCount > 0) {\012    arena.freeCount = arena.freeCount - 1\012    const index = arena.free[arena.freeCount]\012    arena.slots[index] = Some(value)\012    arena.count = arena.count + 1\012    return Handle<T> { index, generation: arena.generations[index] }\012  }\012  const index = Arrays.length(arena.slots)\012  Arrays.push(mutable arena.slots, Some(value))\012  Arrays.push(mutable arena.generations, 0)\012  arena.count = arena.count + 1\012  return Handle<T> { index, generation: 0 }\012}\012\012function pushFree<T>(mutable arena: Arena<T>, index: int) uses alloc {\012  // The free list is a stack: freeCount says how many entries are in use.\012  if (arena.freeCount < Arrays.length(arena.free)) {\012    arena.free[arena.freeCount] = index\012  } else {\012    Arrays.push(mutable arena.free, index)\012  }\012  arena.freeCount = arena.freeCount + 1\012}\012\012function isLive<T>(arena: Arena<T>, handle: Handle<T>): bool {\012  if (handle.index < 0 || handle.index >= Arrays.length(arena.slots)) {\012    return false\012  }\012  if (arena.generations[handle.index] != handle.generation) {\012    return false\012  }\012  return arena.slots[handle.index] is Some(_)\012}\012\012export function contains<T>(arena: Arena<T>, handle: Handle<T>): bool {\012  return isLive(arena, handle)\012}\012\012export function size<T>(arena: Arena<T>): int {\012  return arena.count\012}\012\012export function get<T>(arena: Arena<T>, handle: Handle<T>): Option<T> from arena {\012  if (!isLive(arena, handle)) {\012    return None\012  }\012  return arena.slots[handle.index]\012}\012\012export function set<T>(mutable arena: Arena<T>, handle: Handle<T>, value: T): bool {\012  if (!isLive(arena, handle)) {\012    return false\012  }\012  arena.slots[handle.index] = Some(value)\012  return true\012}\012\012export function update<T, effect E>(\012  mutable arena: Arena<T>,\012  handle: Handle<T>,\012  change: (value: T) => T uses E,\012): bool uses E {\012  if (!isLive(arena, handle)) {\012    return false\012  }\012  // Take the value out first, so the change works on a unique value.\012  const old = arena.slots[handle.index]\012  arena.slots[handle.index] = None\012  if (old is Some(value)) {\012    arena.slots[handle.index] = Some(change(value))\012  }\012  return true\012}\012\012export function remove<T>(mutable arena: Arena<T>, handle: Handle<T>): Option<T> uses alloc {\012  if (!isLive(arena, handle)) {\012    return None\012  }\012  const old = arena.slots[handle.index]\012  arena.slots[handle.index] = None\012  arena.generations[handle.index] = handle.generation + 1\012  pushFree(mutable arena, handle.index)\012  arena.count = arena.count - 1\012  return copy(old)\012}\012\012export function clear<T>(mutable arena: Arena<T>) uses alloc {\012  // Keep the slots and raise every generation, so no old handle matches.\012  arena.freeCount = 0\012  arena.count = 0\012  for (let index = 0; index < Arrays.length(arena.slots); index = index + 1) {\012    arena.slots[index] = None\012    arena.generations[index] = arena.generations[index] + 1\012    pushFree(mutable arena, index)\012  }\012}\012\012export function* entries<T>(arena: Arena<T>): Generator<#[Handle<T>, T]> {\012  for (let index = 0; index < Arrays.length(arena.slots); index = index + 1) {\012    if (arena.slots[index] is Some(value)) {\012      yield #[Handle<T> { index, generation: arena.generations[index] }, value]\012    }\012  }\012}\012"};
static lstr L10789 = {0, 8, "std/args"};
static lstr L10790 = {0, 21201, "// std/args: a command line as data, parsed in one call (D118 item 4).\012//\012// A Command lists its flags, positionals and subcommands. Args.parse reads the\012// arguments `run` receives (the program name first) into a Parsed, or returns\012// an ArgsError. `-h` and `--help` come back as ArgsError.Help: the caller\012// prints Args.help(command, path) and exits 0.\012\012import * as Str from \"std/string\"\012import * as Arrays from \"std/array\"\012\012// A flag. An empty value is a flag without a value; any other text names the\012// value in the help (`--output <path>`). short is one character or empty.\012export struct Flag derives Show, Equatable {\012  name: string\012  short: string = \"\"\012  value: string = \"\"\012  repeated: bool = false\012  help: string = \"\"\012}\012\012// What a command does with positionals after the declared ones: an error\012// (None), collect them (Positionals, flags after them still parse), or keep\012// everything after the declared positionals as written (Raw).\012export enum Rest derives Show, Equatable {\012  None\012  Positionals\012  Raw\012}\012\012export struct Command derives Show, Equatable {\012  name: string\012  summary: string = \"\"\012  flags: Array<Flag> = []\012  positionals: Array<string> = []\012  rest: Rest = Rest.None\012  commands: Array<Command> = []\012}\012\012// One flag or positional as given. A flag without a value has the value \"\".\012export struct Entry derives Show, Equatable {\012  name: string\012  value: string\012}\012\012export struct Parsed derives Show, Equatable {\012  path: Array<string>\012  flags: Array<Entry>\012  positionals: Array<Entry>\012  rest: Array<string>\012}\012\012// The ways a parse fails. closest is the nearest known name for a hint, or \"\".\012// UnknownFlag and MissingValue name the flag as it was typed (`-o` or\012// `--output`); UnexpectedValue and Repeated give its long name.\012export enum ArgsError derives Show, Equatable {\012  UnknownFlag(name: string, closest: string)\012  MissingValue(flag: string)\012  UnexpectedValue(flag: string)\012  Repeated(flag: string)\012  UnknownCommand(name: string, closest: string)\012  MissingCommand(path: Array<string>)\012  MissingPositional(name: string)\012  ExtraPositional(text: string)\012  Help(path: Array<string>)\012  BadSpec(reason: string)\012}\012\012const HELP_FLAG = Flag { name: \"help\", short: \"h\", help: \"print this help\" }\012\012// A name may be a hint when it is at most this many edits away.\012const HINT_DISTANCE = 2\012\012// A name needs at least this many bytes to get a hint.\012const HINT_LENGTH = 3\012\012struct Walk {\012  command: Command\012  path: Array<string>\012  flags: Array<Entry>\012  positionals: Array<Entry>\012  rest: Array<string>\012  // How many of the command's declared positionals are filled.\012  filled: int\012}\012\012export function parse(\012  command: Command,\012  arguments: Array<string>,\012): Result<Parsed, ArgsError> uses alloc {\012  const problem = checkSpec(command, [])\012  if (problem != \"\") {\012    return Err(ArgsError.BadSpec(problem))\012  }\012  let walk = Walk {\012    command: copy(command),\012    path: [command.name],\012    flags: [],\012    positionals: [],\012    rest: [],\012    filled: 0,\012  }\012  // The result keeps texts of the arguments, so it reads a copy of its own.\012  const given = copy(arguments)\012  const count = Arrays.length(given)\012  let flagsEnded = false\012  let index = 1\012  while (index < count) {\012    const argument = given[index]\012    index += 1\012    if (!flagsEnded && argument == \"--\") {\012      flagsEnded = true\012      continue\012    }\012    if (!flagsEnded && Str.startsWith(argument, \"--\")) {\012      const next = readLong(mutable walk, argument, given, index)\012      if (next is Err(error)) {\012        return Err(error)\012      }\012      index = next.value\012      continue\012    }\012    if (!flagsEnded && Str.startsWith(argument, \"-\") && argument != \"-\") {\012      const next = readShorts(mutable walk, argument, given, index)\012      if (next is Err(error)) {\012        return Err(error)\012      }\012      index = next.value\012      continue\012    }\012    // A positional: a subcommand name, a declared positional or the rest.\012    if (Arrays.length(walk.command.commands) > 0) {\012      const chosen = enterCommand(mutable walk, argument)\012      if (chosen is Err(error)) {\012        return Err(error)\012      }\012      continue\012    }\012    if (walk.filled < Arrays.length(walk.command.positionals)) {\012      const name = walk.command.positionals[walk.filled]\012      Arrays.push(mutable walk.positionals, Entry { name, value: argument })\012      walk.filled += 1\012      if (walk.command.rest == Rest.Raw && walk.filled == Arrays.length(walk.command.positionals)) {\012        // After the last declared positional, everything is kept as written.\012        while (index < count) {\012          Arrays.push(mutable walk.rest, given[index])\012          index += 1\012        }\012      }\012      continue\012    }\012    if (walk.command.rest == Rest.Raw) {\012      // A command with no declared positionals keeps everything from here on.\012      Arrays.push(mutable walk.rest, argument)\012      while (index < count) {\012        Arrays.push(mutable walk.rest, given[index])\012        index += 1\012      }\012      continue\012    }\012    if (walk.command.rest == Rest.Positionals) {\012      Arrays.push(mutable walk.rest, argument)\012      continue\012    }\012    return Err(ArgsError.ExtraPositional(argument))\012  }\012  // Every level with subcommands needs one, and every declared positional a value.\012  if (Arrays.length(walk.command.commands) > 0) {\012    return Err(ArgsError.MissingCommand(copy(walk.path)))\012  }\012  if (walk.filled < Arrays.length(walk.command.positionals)) {\012    return Err(ArgsError.MissingPositional(walk.command.positionals[walk.filled]))\012  }\012  return Ok(Parsed {\012    path: walk.path,\012    flags: walk.flags,\012    positionals: walk.positionals,\012    rest: walk.rest,\012  })\012}\012\012// readLong reads `--name`, `--name=value` or `--name value` and returns the\012// index of the next argument.\012function readLong(\012  mutable walk: Walk,\012  argument: string,\012  arguments: Array<string>,\012  index: int,\012): Result<int, ArgsError> uses alloc {\012  const body = Str.sliceFrom(argument, 2)\012  let name = body\012  let inline = \"\"\012  let hasInline = false\012  const equals = Str.indexOf(body, \"=\")\012  if (equals is Some(at)) {\012    name = cutText(body, 0, at)\012    inline = Str.sliceFrom(body, at + 1)\012    hasInline = true\012  }\012  if (name == \"help\" && findLong(walk.command, \"help\") is None) {\012    if (hasInline) {\012      return Err(ArgsError.UnexpectedValue(\"help\"))\012    }\012    return Err(ArgsError.Help(copy(walk.path)))\012  }\012  const found = findLong(walk.command, name)\012  if (found is None) {\012    if (name == \"\") {\012      return Err(ArgsError.UnknownFlag(argument, \"\"))\012    }\012    const closest = closestName(name, longNames(walk.command))\012    if (closest == \"\") {\012      return Err(ArgsError.UnknownFlag(`--${name}`, \"\"))\012    }\012    return Err(ArgsError.UnknownFlag(`--${name}`, `--${closest}`))\012  }\012  const flag = walk.command.flags[found.value]\012  if (flag.value == \"\") {\012    if (hasInline) {\012      return Err(ArgsError.UnexpectedValue(flag.name))\012    }\012    return addFlag(mutable walk, flag, \"\", index)\012  }\012  if (hasInline) {\012    return addFlag(mutable walk, flag, inline, index)\012  }\012  if (index >= Arrays.length(arguments)) {\012    return Err(ArgsError.MissingValue(`--${flag.name}`))\012  }\012  return addFlag(mutable walk, flag, arguments[index], index + 1)\012}\012\012// readShorts reads `-x`, `-x value`, `-xvalue` and bundled `-abc`, and returns\012// the index of the next argument.\012function readShorts(\012  mutable walk: Walk,\012  argument: string,\012  arguments: Array<string>,\012  index: int,\012): Result<int, ArgsError> uses alloc {\012  const length = Str.length(argument)\012  // The byte offset of the next character of the bundle.\012  let offset = 1\012  for (const character of Str.chars(Str.sliceFrom(argument, 1))) {\012    const short = Str.fromChar(character)\012    offset += Str.length(short)\012    const found = findShort(walk.command, short)\012    if (found is None) {\012      if (short == \"h\") {\012        return Err(ArgsError.Help(copy(walk.path)))\012      }\012      return Err(ArgsError.UnknownFlag(`-${short}`, \"\"))\012    }\012    const flag = walk.command.flags[found.value]\012    if (flag.value == \"\") {\012      const added = addFlag(mutable walk, flag, \"\", index)\012      if (added is Err(error)) {\012        return Err(error)\012      }\012      continue\012    }\012    // A flag with a value takes the rest of the bundle, or the next argument.\012    if (offset < length) {\012      return addFlag(mutable walk, flag, Str.sliceFrom(argument, offset), index)\012    }\012    if (index >= Arrays.length(arguments)) {\012      return Err(ArgsError.MissingValue(`-${short}`))\012    }\012    return addFlag(mutable walk, flag, arguments[index], index + 1)\012  }\012  return Ok(index)\012}\012\012function addFlag(\012  mutable walk: Walk,\012  flag: Flag,\012  value: string,\012  next: int,\012): Result<int, ArgsError> uses alloc {\012  if (!flag.repeated && findEntry(walk.flags, flag.name) is Some(_)) {\012    return Err(ArgsError.Repeated(flag.name))\012  }\012  Arrays.push(mutable walk.flags, Entry { name: flag.name, value })\012  return Ok(next)\012}\012\012// enterCommand moves the walk into the subcommand named text.\012function enterCommand(mutable walk: Walk, text: string): Result<int, ArgsError> uses alloc {\012  let names: Array<string> = []\012  let position = -1\012  for (const #[index, command] of Arrays.entries(walk.command.commands)) {\012    Arrays.push(mutable names, command.name)\012    if (command.name == text && position < 0) {\012      position = index\012    }\012  }\012  if (position < 0) {\012    return Err(ArgsError.UnknownCommand(text, closestName(text, names)))\012  }\012  const next = copy(walk.command.commands[position])\012  walk.command = next\012  Arrays.push(mutable walk.path, text)\012  walk.filled = 0\012  return Ok(position)\012}\012\012function findLong(command: Command, name: string): Option<int> {\012  for (const #[index, flag] of Arrays.entries(command.flags)) {\012    if (flag.name == name) {\012      return Some(index)\012    }\012  }\012  return None\012}\012\012function findShort(command: Command, short: string): Option<int> {\012  for (const #[index, flag] of Arrays.entries(command.flags)) {\012    if (flag.short != \"\" && flag.short == short) {\012      return Some(index)\012    }\012  }\012  return None\012}\012\012function findEntry(entries: Array<Entry>, name: string): Option<int> {\012  for (const #[index, entry] of Arrays.entries(entries)) {\012    if (entry.name == name) {\012      return Some(index)\012    }\012  }\012  return None\012}\012\012// The long names a command accepts, without their dashes.\012function longNames(command: Command): Array<string> uses alloc {\012  let names: Array<string> = []\012  for (const flag of command.flags) {\012    Arrays.push(mutable names, flag.name)\012  }\012  if (findLong(command, \"help\") is None) {\012    Arrays.push(mutable names, \"help\")\012  }\012  return names\012}\012\012// checkSpec returns the first mistake in the spec, or \"\". inherited holds the\012// long names of the enclosing commands: Parsed keeps flags by name, so a\012// subcommand may not reuse one.\012function checkSpec(command: Command, inherited: Array<string>): string uses alloc {\012  let longs: Array<string> = []\012  let shorts: Array<string> = []\012  for (const flag of command.flags) {\012    if (flag.name == \"\") {\012      return `command ${command.name} has a flag with an empty name`\012    }\012    if (Arrays.length(longs) > 0 && containsText(longs, flag.name)) {\012      return `command ${command.name} has two flags named --${flag.name}`\012    }\012    if (containsText(inherited, flag.name)) {\012      return `command ${command.name} reuses --${flag.name}, a flag of an enclosing command`\012    }\012    Arrays.push(mutable longs, flag.name)\012    if (flag.short != \"\") {\012      if (Str.charCount(flag.short) != 1) {\012        return `flag --${flag.name} has the short name \"${flag.short}\", which is not one character`\012      }\012      if (flag.short == \"-\") {\012        return `flag --${flag.name} has the short name \"-\"`\012      }\012      if (containsText(shorts, flag.short)) {\012        return `command ${command.name} has two flags with the short name -${flag.short}`\012      }\012      Arrays.push(mutable shorts, flag.short)\012    }\012  }\012  let positionals: Array<string> = []\012  for (const name of command.positionals) {\012    if (containsText(positionals, name)) {\012      return `command ${command.name} has two positionals named <${name}>`\012    }\012    Arrays.push(mutable positionals, name)\012  }\012  if (Arrays.length(command.commands) > 0 && Arrays.length(command.positionals) > 0) {\012    return `command ${command.name} has both positionals and subcommands`\012  }\012  // The subcommands see the long names of this command and of its parents.\012  let enclosing = copy(inherited)\012  for (const name of longs) {\012    Arrays.push(mutable enclosing, name)\012  }\012  let names: Array<string> = []\012  for (const sub of command.commands) {\012    if (containsText(names, sub.name)) {\012      return `command ${command.name} has two subcommands named ${sub.name}`\012    }\012    Arrays.push(mutable names, sub.name)\012    const problem = checkSpec(sub, enclosing)\012    if (problem != \"\") {\012      return problem\012    }\012  }\012  return \"\"\012}\012\012function containsText(items: Array<string>, text: string): bool {\012  for (const item of items) {\012    if (item == text) {\012      return true\012    }\012  }\012  return false\012}\012\012function cutText(text: string, start: int, end: int): string uses alloc {\012  if (Str.slice(text, start, end) is Some(piece)) {\012    return piece\012  }\012  return \"\"\012}\012\012// closestName returns the candidate fewest edits from text, at most\012// HINT_DISTANCE away, or \"\". The first one wins a tie. A name shorter than\012// HINT_LENGTH gets no hint, since two edits reach any other short name.\012function closestName(text: string, candidates: Array<string>): string uses alloc {\012  if (Str.length(text) < HINT_LENGTH) {\012    return \"\"\012  }\012  let best = \"\"\012  let bestDistance = HINT_DISTANCE + 1\012  for (const candidate of candidates) {\012    const distance = editDistance(text, candidate)\012    if (distance < bestDistance) {\012      best = candidate\012      bestDistance = distance\012    }\012  }\012  return best\012}\012\012// editDistance is the Levenshtein distance over the bytes of two names.\012function editDistance(left: string, right: string): int uses alloc {\012  const leftLength = Str.length(left)\012  const rightLength = Str.length(right)\012  let previous: Array<int> = Arrays.withCapacity(rightLength + 1)\012  for (let j = 0; j <= rightLength; j++) {\012    Arrays.push(mutable previous, j)\012  }\012  for (let i = 1; i <= leftLength; i++) {\012    let current: Array<int> = Arrays.withCapacity(rightLength + 1)\012    Arrays.push(mutable current, i)\012    for (let j = 1; j <= rightLength; j++) {\012      let cost = 1\012      if (Str.byteAt(left, i - 1) == Str.byteAt(right, j - 1)) {\012        cost = 0\012      }\012      let best = previous[j - 1] + cost\012      if (previous[j] + 1 < best) {\012        best = previous[j] + 1\012      }\012      if (current[j - 1] + 1 < best) {\012        best = current[j - 1] + 1\012      }\012      Arrays.push(mutable current, best)\012    }\012    previous = current\012  }\012  return previous[rightLength]\012}\012\012export function has(parsed: Parsed, name: string): bool {\012  return findEntry(parsed.flags, name) is Some(_)\012}\012\012// value returns the last value given for the flag name.\012export function value(parsed: Parsed, name: string): Option<string> uses alloc {\012  let found: Option<string> = None\012  for (const entry of parsed.flags) {\012    if (entry.name == name) {\012      found = Some(entry.value)\012    }\012  }\012  return found\012}\012\012export function values(parsed: Parsed, name: string): Array<string> uses alloc {\012  let found: Array<string> = []\012  for (const entry of parsed.flags) {\012    if (entry.name == name) {\012      Arrays.push(mutable found, entry.value)\012    }\012  }\012  return found\012}\012\012export function positional(parsed: Parsed, name: string): Option<string> uses alloc {\012  for (const entry of parsed.positionals) {\012    if (entry.name == name) {\012      return Some(entry.value)\012    }\012  }\012  return None\012}\012\012export function rest(parsed: Parsed): Array<string> uses alloc {\012  return copy(parsed.rest)\012}\012\012export function commandPath(parsed: Parsed): Array<string> uses alloc {\012  return copy(parsed.path)\012}\012\012// help writes the help of the command at path (`[\"narrac\", \"build\"]`): the\012// usage line, the summary, the flags and the subcommands, in aligned columns.\012export function help(command: Command, path: Array<string>): string uses alloc {\012  let target = copy(command)\012  let names: Array<string> = [command.name]\012  for (const #[index, name] of Arrays.entries(path)) {\012    if (index == 0) {\012      continue\012    }\012    const found = findCommand(target, name)\012    if (found is None) {\012      break\012    }\012    const next = copy(target.commands[found.value])\012    target = next\012    Arrays.push(mutable names, name)\012  }\012  let builder = Str.builder()\012  Str.append(mutable builder, `Usage: ${Str.join(names, \" \")} [flags]`)\012  for (const name of target.positionals) {\012    Str.append(mutable builder, ` <${name}>`)\012  }\012  if (target.rest == Rest.Positionals) {\012    Str.append(mutable builder, \" [arguments...]\")\012  } else if (target.rest == Rest.Raw) {\012    Str.append(mutable builder, \" [arguments...]\")\012  }\012  if (Arrays.length(target.commands) > 0) {\012    Str.append(mutable builder, \" <command>\")\012  }\012  Str.append(mutable builder, \"\\n\")\012  if (target.summary != \"\") {\012    Str.append(mutable builder, `\\n${target.summary}\\n`)\012  }\012  // The flag column, with the added help flag last.\012  let flags = copy(target.flags)\012  if (findLong(target, \"help\") is None) {\012    if (findShort(target, \"h\") is None) {\012      Arrays.push(mutable flags, HELP_FLAG)\012    } else {\012      Arrays.push(mutable flags, Flag { name: \"help\", help: \"print this help\" })\012    }\012  }\012  let labels: Array<string> = []\012  let texts: Array<string> = []\012  for (const flag of flags) {\012    Arrays.push(mutable labels, flagLabel(flag))\012    Arrays.push(mutable texts, flag.help)\012  }\012  Str.append(mutable builder, \"\\nFlags:\\n\")\012  writeColumns(mutable builder, labels, texts)\012  if (Arrays.length(target.commands) > 0) {\012    let commandNames: Array<string> = []\012    let summaries: Array<string> = []\012    for (const sub of target.commands) {\012      Arrays.push(mutable commandNames, sub.name)\012      Arrays.push(mutable summaries, sub.summary)\012    }\012    Str.append(mutable builder, \"\\nCommands:\\n\")\012    writeColumns(mutable builder, commandNames, summaries)\012  }\012  return Str.build(builder)\012}\012\012function findCommand(command: Command, name: string): Option<int> {\012  for (const #[index, sub] of Arrays.entries(command.commands)) {\012    if (sub.name == name) {\012      return Some(index)\012    }\012  }\012  return None\012}\012\012// flagLabel writes `-o, --output <path>`, or `    --release` without a short name.\012function flagLabel(flag: Flag): string uses alloc {\012  let label = \"    \"\012  if (flag.short != \"\") {\012    label = `-${flag.short}, `\012  }\012  label = `${label}--${flag.name}`\012  if (flag.value != \"\") {\012    label = `${label} <${flag.value}>`\012  }\012  if (flag.repeated) {\012    label = `${label}...`\012  }\012  return label\012}\012\012// writeColumns writes one line per label, with the texts lined up after the\012// widest label.\012function writeColumns(\012  mutable builder: StringBuilder,\012  labels: Array<string>,\012  texts: Array<string>,\012) uses alloc {\012  let width = 0\012  for (const label of labels) {\012    if (visibleWidth(label) > width) {\012      width = visibleWidth(label)\012    }\012  }\012  for (const #[index, label] of Arrays.entries(labels)) {\012    Str.append(mutable builder, `  ${label}`)\012    if (texts[index] != \"\") {\012      if (Str.repeat(\" \", width - visibleWidth(label) + 2) is Some(padding)) {\012        Str.append(mutable builder, padding)\012      }\012      Str.append(mutable builder, texts[index])\012    }\012    Str.append(mutable builder, \"\\n\")\012  }\012}\012\012// visibleWidth counts the code points of a label, without the escape\012// sequences (`ESC [`, parameters, a final byte) that style it.\012function visibleWidth(text: string): int {\012  const length = Str.length(text)\012  let width = 0\012  let index = 0\012  while (index < length) {\012    const byte = Str.byteAt(text, index)\012    if (byte == 27 && index + 1 < length && Str.byteAt(text, index + 1) == 91) {\012      // Skip parameter and intermediate bytes, then the final byte.\012      index += 2\012      while (index < length && Str.byteAt(text, index) >= 32 && Str.byteAt(text, index) <= 63) {\012        index += 1\012      }\012      index += 1\012      continue\012    }\012    // Count the first byte of each code point, not its continuation bytes.\012    if (byte < 128 || byte >= 192) {\012      width += 1\012    }\012    index += 1\012  }\012  return width\012}\012\012// formatError writes the message line of an error, with a hint when a known\012// name is close (`unknown flag --relase; did you mean --release\077`).\012export function formatError(error: ArgsError): string uses alloc {\012  return match (error) {\012    ArgsError.UnknownFlag(name, closest) => withHint(`unknown flag ${name}`, closest)\012    ArgsError.MissingValue(flag) => `flag ${flag} needs a value`\012    ArgsError.UnexpectedValue(flag) => `flag --${flag} takes no value`\012    ArgsError.Repeated(flag) => `flag --${flag} is given more than once`\012    ArgsError.UnknownCommand(name, closest) => withHint(`unknown command ${name}`, closest)\012    ArgsError.MissingCommand(path) => `${Str.join(path, \" \")} needs a command`\012    ArgsError.MissingPositional(name) => `missing argument <${name}>`\012    ArgsError.ExtraPositional(text) => `unexpected argument ${text}`\012    ArgsError.Help(path) => `help for ${Str.join(path, \" \")}`\012    ArgsError.BadSpec(reason) => `bad command spec: ${reason}`\012  }\012}\012\012function withHint(message: string, closest: string): string uses alloc {\012  if (closest == \"\") {\012    return message\012  }\012  return `${message}; did you mean ${closest}\077`\012}\012"};
