static lstr L10834 = {0, 2117, "// std/parallel: Parallel.map runs a function over an array on several threads\012// (SPEC.md section 8, D111 item 4). The array is split into one part per core,\012// each part runs on a thread of its own, and the results keep the order of\012// the items. Importing this module builds the program in thread mode (D111\012// item 2).\012\012import * as Arrays from \"std/array\"\012import * as Boxes from \"std/box\"\012import * as CellSlot from \"std/internal/cell\"\012import * as Threads from \"std/internal/thread\"\012\012// Gives change(item) for every item, in the order of the items. As for\012// Thread.start, the items, the result and the captures of change must be\012// Sendable, and change must be an arrow function written at the call or the\012// name of a top-level function.\012export function map<T, U, effect E>(\012  items: Array<T>,\012  escaping change: (item: T) => U uses E,\012): Array<U> uses E, alloc {\012  const count = Arrays.length(items)\012  let parts = Threads.cores()\012  if (parts > count) {\012    parts = count\012  }\012  let results: Array<Box<Array<U>>> = []\012  let threads: Array<int> = []\012  let start = 0\012  for (let part = 0; part < parts; part++) {\012    // The first count % parts parts take one item more.\012    let size = count / parts\012    if (part < count % parts) {\012      size++\012    }\012    const first = start\012    const end = start + size\012    const slot: Box<Array<U>> = Boxes.new([])\012    const thread = Threads.start(() => CellSlot.store(slot, mapPart(items, first, end, change)))\012    Arrays.push(mutable threads, thread)\012    Arrays.push(mutable results, slot)\012    start = end\012  }\012  for (const thread of Arrays.values(threads)) {\012    Threads.join(thread)\012  }\012  let output: Array<U> = []\012  for (const slot of Arrays.values(results)) {\012    for (const value of Arrays.values(slot.value)) {\012      Arrays.push(mutable output, value)\012    }\012  }\012  return output\012}\012\012function mapPart<T, U, effect E>(\012  items: Array<T>,\012  first: int,\012  end: int,\012  change: (item: T) => U uses E,\012): Array<U> uses E, alloc {\012  let mapped: Array<U> = []\012  for (let index = first; index < end; index++) {\012    Arrays.push(mutable mapped, change(items[index]))\012  }\012  return mapped\012}\012"};
